from sympy import Rational, floor, jacobi_symbol, gcd
def saw(x): return 0 if x==floor(x) else x-floor(x)-Rational(1,2)
def ded(m,n): return 12*n*sum(saw(Rational(r,n))*saw(Rational(m*r,n)) for r in range(1,n))
all((jacobi_symbol(2*m%n,n) - (Rational(1,2)*(1+jacobi_symbol(n-1,n)) - ded(m,n)/2)) % 4 == 0 for n in range(3,60,2) for m in range(1,n) if gcd(m,n)==1)
